@startuml

class Person {
  +name : string
  +address : string
}

class CLIENT extends Person {
  +phone_number : string
  +contact_person : string
}

class WORKER extends Person {
  +birth_date : date
  +skills : string[]
}

class MACHINE {
  +serial_number : string
  +make : string
  +model : string
  +purchase_date : date
}

class PRODUCT_TYPE {
  +name : string
  +material : string
  +weight : float
}

class PRODUCT {
  +name : string
}

class PURCHASE_ORDER {
  +order_number : string
  +date_made : date
  +expected_delivery_date : date
  +actual_delivery_date : date
}

class ORDER_LINE {
  +quantity : int
}

WORKER "*" -- "*" MACHINE
MACHINE "1" -- "*" PRODUCT_TYPE
PRODUCT_TYPE "1" -- "*" PRODUCT
CLIENT "1" -- "*" PURCHASE_ORDER
PURCHASE_ORDER "1" *-- "*" ORDER_LINE
ORDER_LINE "*" -- "1" PRODUCT

@enduml

